/bin/bash -lc "python - <<'PY'
import urllib.request
for url in ['https://developers.openai.com/api/reference/resources/responses/methods/create','https://platform.openai.com/docs/guides/your-data']:
    try:
        with urllib.request.urlopen(url, timeout=25) as response:
            data=response.read().decode()
        import re
        clean=re.sub('<["'^>]+>'"', ' ', data)
        clean=re.sub(r'\\s+', ' ', clean)
        print('SOURCE',url)
        for term in ['store', 'output_text', 'abuse monitoring', '30 days']:
            match=re.search(term,clean,re.I)
            if match: print(clean[max(0,match.start()-200):match.start()+550])
    except Exception as exc:
        print(type(exc).__name__,str(exc))
PY"

